function hasRisingTriple(nums: number[]): boolean {
  const n = nums.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      if (nums[i] < nums[j])
        for (let k = j + 1; k < n; k++)
          if (nums[j] < nums[k]) return true;
  return false;
}

