function hasRisingTriple(nums: number[]): boolean {
  const n = nums.length;
  const sufMax = new Array<number>(n).fill(-Infinity);
  for (let i = n - 2; i >= 0; i--) sufMax[i] = Math.max(sufMax[i + 1], nums[i + 1]);
  let preMin = Infinity;
  for (let j = 0; j < n; j++) {
    if (preMin < nums[j] && nums[j] < sufMax[j]) return true;
    preMin = Math.min(preMin, nums[j]);
  }
  return false;
}

